/// The match of rules.rs authorize and may_attempt: the policy names a role held, the action and the resource, where AnyObject covers every Object; the condition aside.
///
/// Specification function `policy-applies`.
pub fn policy_applies(
    policy: &types::PolicyDef,
    roles: &std::collections::BTreeSet<types::RoleId>,
    action: &types::Action,
    resource: &types::Resource,
) -> bool {
    roles.iter().any(|r| *r == policy.role)
        && policy.actions.iter().any(|a| *a == *action)
        && (match &policy.resource {
            types::Resource::AnyObject => match resource {
                types::Resource::Object(_) => true,
                _ => policy.resource == *resource,
            },
            _ => policy.resource == *resource,
        })
}

/// crates/kernel/src/rules.rs may_attempt: whether some policy of the tenant schema could grant the action, conditions aside, or whether a permission of one of its roles grants the verb on the object type; the owner may do anything. For user interfaces; the decision is authorize.
///
/// Specification function `may-attempt`.
pub fn may_attempt(
    tenant: &types::TenantState,
    principal: &types::Principal,
    action: &types::Action,
    resource: &types::Resource,
) -> bool {
    let roles = roles_of(tenant, principal);
    roles.iter().any(|r| r.0 == "owner")
        || effective_permissions(tenant, principal)
            .iter()
            .any(|g| grant_allows(g, action, resource))
        || tenant
            .schema
            .policies
            .values()
            .any(|p| policy_applies(p, &roles, action, resource))
}

