    /// Example 1 of `validation-into-result`.
    #[test]
    fn validation_into_result_example_1() {
        let outcome: types::ValidationOutcome = types::ValidationOutcome {
            passed: vec![types::Check {
                rule: "type:note.title".to_string(),
                passed: true,
                detail: "string".to_string(),
            }],
            failed: Vec::new(),
        };
        let evidence: Vec<types::Check> = vec![types::Check {
            rule: "policy:writers_read_notes".to_string(),
            passed: true,
            detail: "Create on Object(ObjectTypeId(\"note\"))".to_string(),
        }];
        let want_: Vec<types::Check> = vec![
            types::Check {
                rule: "policy:writers_read_notes".to_string(),
                passed: true,
                detail: "Create on Object(ObjectTypeId(\"note\"))".to_string(),
            },
            types::Check {
                rule: "type:note.title".to_string(),
                passed: true,
                detail: "string".to_string(),
            },
        ];
        assert_eq!(validation_into_result(&outcome, &evidence), Ok(want_));
    }

    /// Example 2 of `validation-into-result`.
    #[test]
    fn validation_into_result_example_2() {
        let outcome: types::ValidationOutcome = types::ValidationOutcome {
            passed: vec![types::Check {
                rule: "required:note.slug".to_string(),
                passed: true,
                detail: "present".to_string(),
            }],
            failed: vec![
                types::ValidationFailure {
                    check: types::Check {
                        rule: "required:note.title".to_string(),
                        passed: false,
                        detail: "a value is required".to_string(),
                    },
                    kind: types::ErrorKind::MissingRequired,
                },
                types::ValidationFailure {
                    check: types::Check {
                        rule: "type:note.rank".to_string(),
                        passed: false,
                        detail: "expected int, found string".to_string(),
                    },
                    kind: types::ErrorKind::TypeMismatch,
                },
            ],
        };
        let evidence: Vec<types::Check> = Vec::new();
        assert_eq!(
            validation_into_result(&outcome, &evidence),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::MissingRequired,
                message: "required:note.title: a value is required".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "required:note.slug".to_string(),
                        passed: true,
                        detail: "present".to_string()
                    },
                    types::Check {
                        rule: "required:note.title".to_string(),
                        passed: false,
                        detail: "a value is required".to_string()
                    },
                    types::Check {
                        rule: "type:note.rank".to_string(),
                        passed: false,
                        detail: "expected int, found string".to_string()
                    }
                ],
                missing: None
            }))
        );
    }

