    fn draft_reject_example_1() {
        let evidence: Vec<types::Check> = vec![types::Check {
            rule: "default:note.status".to_string(),
            passed: true,
            detail: "'draft'".to_string(),
        }];
        let kind: types::ErrorKind = types::ErrorKind::Evaluation;
        let message: String = "default of x: oops".to_string();
        let want_: types::Rejection = types::Rejection::Rejected(types::DomainError {
            kind: types::ErrorKind::Evaluation,
            message: "default of x: oops".to_string(),
            evidence: vec![
                types::Check {
                    rule: "default:note.status".to_string(),
                    passed: true,
                    detail: "'draft'".to_string(),
                },
                types::Check {
                    rule: "intent:evaluation".to_string(),
                    passed: false,
                    detail: "default of x: oops".to_string(),
                },
            ],
            missing: None,
        });
        assert_eq!(draft_reject(&evidence, &kind, &message), want_);
    }

