    /// behaviour.rs a_stale_expected_version_is_a_conflict.
    #[test]
    fn check_version_example_1() {
        let d: types::Draft = {
            let mut fixture = fixture_fx_draft_4();
            fixture.evidence = vec![types::Check {
                rule: "policy:writers_edit_own".to_string(),
                passed: true,
                detail: "x".to_string(),
            }];
            fixture
        };
        let record: types::Record = types::Record {
            id: types::RecordId(1),
            object: types::ObjectTypeId("note".to_string()),
            version: 2,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("slug".to_string()),
                    types::Value::Str("first".to_string()),
                ),
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("draft".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("First".to_string()),
                ),
            ]),
        };
        let expected: Option<u64> = Some(1);
        assert_eq!(
            check_version(&d, &record, expected),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::VersionConflict,
                message: "record is at version 2, expected 1".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "policy:writers_edit_own".to_string(),
                        passed: true,
                        detail: "x".to_string()
                    },
                    types::Check {
                        rule: "intent:version_conflict".to_string(),
                        passed: false,
                        detail: "record is at version 2, expected 1".to_string()
                    }
                ],
                missing: None
            }))
        );
    }

