    /// behaviour.rs every_rejection_lists_at_least_one_failed_check: unknown record, for an editor, who may update any note and so learns that it is missing.
    #[test]
    fn stored_example_2() {
        let d: types::Draft = fixture_fx_draft_6();
        let object: types::ObjectTypeId = types::ObjectTypeId("note".to_string());
        let id: types::RecordId = types::RecordId(42);
        let action: types::Action = types::Action::Update;
        assert_eq!(
            stored(&d, &object, &id, &action),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::UnknownRecord,
                    message: "no note 42".to_string(),
                    evidence: vec![
                        types::Check {
                            rule: "policy:editors_manage_notes".to_string(),
                            passed: true,
                            detail: "Update on Object(ObjectTypeId(\"note\"))".to_string()
                        },
                        types::Check {
                            rule: "intent:unknown_record".to_string(),
                            passed: false,
                            detail: "no note 42".to_string()
                        }
                    ],
                    missing: None
                }
            )))
        );
    }

