    fn initial_checks_example_4() {
        let d: types::Draft = fixture_fx_draft_9();
        let object: types::ObjectTypeId = types::ObjectTypeId("note".to_string());
        let candidate: types::Record = types::Record {
            id: types::RecordId(1),
            object: types::ObjectTypeId("note".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("slug".to_string()),
                    types::Value::Str("first".to_string()),
                ),
                (types::FieldId("status".to_string()), types::Value::Int(3)),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("First".to_string()),
                ),
            ]),
        };
        assert_eq!(
            initial_checks(&d, &object, &candidate),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::WorkflowViolation,
                message: "Int(3) is not an initial state of note_status".to_string(),
                evidence: vec![types::Check {
                    rule: "workflow:note_status:initial".to_string(),
                    passed: false,
                    detail: "a new record must start in one of {\"draft\"}".to_string()
                }],
                missing: None
            }))
        );
    }

