    /// Removing a query that is not there is a problem.
    #[test]
    fn apply_change_example_19() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange =
            types::SchemaChange::RemoveQuery(types::QueryId("nope".to_string()));
        assert_eq!(
            apply_change(&schema, &change),
            Err(types::SchemaProblem::Problem("no query nope".to_string()))
        );
    }

