    /// Removing a unit that is not declared is refused.
    #[test]
    fn apply_change_example_71() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange =
            types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Unit {
                unit: types::LedgerUnit("credits".to_string()),
            });
        assert_eq!(
            apply_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "no ledger unit credits".to_string()
            ))
        );
    }

    /// Removing a pool that is not declared is refused.
