    /// Example 1 of `touched-objects`.
    #[test]
    fn touched_objects_example_1() {
        let changes: Vec<types::SchemaChange> = vec![
            types::SchemaChange::DefineRelationship {
                object: types::ObjectTypeId("note".to_string()),
                field: types::FieldId("editor".to_string()),
                label: "Editor".to_string(),
                target: types::ObjectTypeId("person".to_string()),
                on_delete: types::OnDelete::Restrict,
                required: false,
            },
            types::SchemaChange::DefineRole(types::RoleDef {
                id: types::RoleId("guest".to_string()),
                label: "Guest".to_string(),
            }),
            types::SchemaChange::RemoveField {
                object: types::ObjectTypeId("note".to_string()),
                field: types::FieldId("body".to_string()),
            },
        ];
        let want_: std::collections::BTreeSet<types::ObjectTypeId> =
            std::collections::BTreeSet::from([
                types::ObjectTypeId("note".to_string()),
                types::ObjectTypeId("person".to_string()),
            ]);
        assert_eq!(touched_objects(&changes), want_);
    }

