    fn touched_objects_example_5() {
        let changes: Vec<types::SchemaChange> = vec![
            types::SchemaChange::DefineUnique {
                object: types::ObjectTypeId("note".to_string()),
                unique: types::UniqueDef {
                    id: types::ConstraintId("title_status".to_string()),
                    fields: vec![
                        types::FieldId("title".to_string()),
                        types::FieldId("status".to_string()),
                    ],
                    message: "One note per title and status.".to_string(),
                },
            },
            types::SchemaChange::RemoveUnique {
                object: types::ObjectTypeId("tag".to_string()),
                unique: types::ConstraintId("x".to_string()),
            },
        ];
        let want_: std::collections::BTreeSet<types::ObjectTypeId> =
            std::collections::BTreeSet::from([
                types::ObjectTypeId("note".to_string()),
                types::ObjectTypeId("tag".to_string()),
            ]);
        assert_eq!(touched_objects(&changes), want_);
    }

