    /// Example 3 of `lookup-all`.
    #[test]
    fn lookup_all_example_3() {
        let tenant: types::TenantState = fixture_fx_tenant_state_9();
        let coverage: types::Coverage =
            types::Coverage::Partial(std::collections::BTreeSet::from([types::Need::Record {
                object: types::ObjectTypeId("note".to_string()),
                id: types::RecordId(1),
            }]));
        let object: types::ObjectTypeId = types::ObjectTypeId("note".to_string());
        assert_eq!(
            lookup_all(&tenant, &coverage, &object),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::InsufficientState,
                message: "the snapshot does not cover AllOf(ObjectTypeId(\"note\"))".to_string(),
                evidence: vec![types::Check {
                    rule: "coverage".to_string(),
                    passed: false,
                    detail: "AllOf(ObjectTypeId(\"note\"))".to_string()
                }],
                missing: Some(types::Need::AllOf(types::ObjectTypeId("note".to_string())))
            }))
        );
    }

