    fn plan_migration_example_3() {
        let tenant: types::TenantState = fixture_fx_tenant_state_10();
        let coverage: types::Coverage = types::Coverage::Complete;
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::RemoveField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("nothing".to_string()),
        }];
        let now: crate::prelude::Timestamp = crate::prelude::Timestamp(5002);
        assert_eq!(
            plan_migration(&tenant, &coverage, &changes, now),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::InvalidSchema,
                    message: "no field note.nothing".to_string(),
                    evidence: vec![types::Check {
                        rule: "schema:change".to_string(),
                        passed: false,
                        detail: "no field note.nothing".to_string()
                    }],
                    missing: None
                }
            )))
        );
    }

