    /// transition.rs plan_migration, CMS-1556: a composite unique constraint is not declared over two records that already share its values; the change is refused with UniqueViolated naming the first pair, after the schema:change checks.
    #[test]
    fn plan_migration_example_6() {
        let tenant: types::TenantState = fixture_fx_tenant_state_11();
        let coverage: types::Coverage = types::Coverage::Complete;
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::DefineUnique {
            object: types::ObjectTypeId("note".to_string()),
            unique: types::UniqueDef {
                id: types::ConstraintId("title_status".to_string()),
                fields: vec![
                    types::FieldId("title".to_string()),
                    types::FieldId("status".to_string()),
                ],
                message: "One note per title and status.".to_string(),
            },
        }];
        let now: crate::prelude::Timestamp = crate::prelude::Timestamp(5002);
        assert_eq!(
            plan_migration(& tenant, & coverage, & changes, now),
            Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
            types::ErrorKind::UniqueViolated, message :
            "unique:note.title_status: records 1 and 2 have the same values in title, status"
            .to_string(), evidence : vec![types::Check { rule : "schema:change"
            .to_string(), passed : true, detail :
            "define unique constraint note.title_status".to_string() }, types::Check {
            rule : "unique:note.title_status".to_string(), passed : false, detail :
            "records 1 and 2 have the same values in title, status".to_string() }],
            missing : None })))
        );
    }

