    /// behaviour.rs an_inconsistent_schema_change_is_rejected_with_the_reason: the draft's evidence comes first.
    #[test]
    fn change_schema_example_7() {
        let d: types::Draft = fixture_fx_draft_14();
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::DefineConstraint {
            object: types::ObjectTypeId("note".to_string()),
            constraint: types::ConstraintDef {
                id: types::ConstraintId("broken".to_string()),
                expr: types::Expr::Cmp(
                    types::CmpOp::Eq,
                    Box::new(types::Expr::Var(
                        types::Scope::New,
                        "no_such_field".to_string(),
                    )),
                    Box::new(types::Expr::Lit(types::Value::Str("x".to_string()))),
                ),
                message: "never".to_string(),
            },
        }];
        let expected_version: Option<types::SchemaVersion> = None;
        let existing: types::ExistingData = types::ExistingData::Reject;
        assert_eq!(
            change_schema(&d, &changes, &expected_version, &existing),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::InvalidSchema,
                    message: "note.broken: unknown field no_such_field".to_string(),
                    evidence: vec![
                        types::Check {
                            rule: "policy:builtin_owner".to_string(),
                            passed: true,
                            detail: "Manage on Schema".to_string()
                        },
                        types::Check {
                            rule: "schema:change".to_string(),
                            passed: true,
                            detail: "define constraint note.broken".to_string()
                        },
                        types::Check {
                            rule: "schema:consistency".to_string(),
                            passed: false,
                            detail: "note.broken: unknown field no_such_field".to_string()
                        }
                    ],
                    missing: None
                }
            )))
        );
    }

    /// An InsufficientState refusal of the plan keeps its missing need.
    #[test]
    fn change_schema_example_8() {
        let d: types::Draft = {
            let mut fixture = fixture_fx_draft_14();
            fixture.coverage = types::Coverage::Partial(std::collections::BTreeSet::new());
            fixture
        };
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::DefineField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldDef {
                id: types::FieldId("rank".to_string()),
                label: "rank".to_string(),
                ty: types::FieldType::Int,
                required: true,
                unique: false,
                default: None,
                read: None,
                personal: None,
            },
        }];
        let expected_version: Option<types::SchemaVersion> = None;
        let existing: types::ExistingData = types::ExistingData::Reject;
        assert_eq!(
            change_schema(&d, &changes, &expected_version, &existing),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::InsufficientState,
                    message: "the snapshot does not cover AllOf(ObjectTypeId(\"note\"))"
                        .to_string(),
                    evidence: vec![
                        types::Check {
                            rule: "policy:builtin_owner".to_string(),
                            passed: true,
                            detail: "Manage on Schema".to_string()
                        },
                        types::Check {
                            rule: "coverage".to_string(),
                            passed: false,
                            detail: "AllOf(ObjectTypeId(\"note\"))".to_string()
                        }
                    ],
                    missing: Some(types::Need::AllOf(types::ObjectTypeId("note".to_string())))
                }
            )))
        );
    }

