    /// A snapshot that does not cover the need of a unit being removed refuses the change as InsufficientState.
    #[test]
    fn change_schema_example_14() {
        let d: types::Draft = {
            let mut fixture = fixture_fx_draft_29();
            fixture.ctx.correlation = "test-6000".to_string();
            fixture
        };
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::RemoveLedgerDefinition(
            types::LedgerDefinitionRef::Unit {
                unit: types::LedgerUnit("credits".to_string()),
            },
        )];
        let expected_version: Option<types::SchemaVersion> = None;
        let existing: types::ExistingData = types::ExistingData::Reject;
        assert_eq!(
            change_schema(& d, & changes, & expected_version, & existing),
            Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
            types::ErrorKind::InsufficientState, message :
            "the snapshot does not cover Ledger(UnitUsed { unit: LedgerUnit(\"credits\") })"
            .to_string(), evidence : vec![types::Check { rule : "coverage".to_string(),
            passed : false, detail : "Ledger(UnitUsed { unit: LedgerUnit(\"credits\") })"
            .to_string() }], missing :
            Some(types::Need::Ledger(types::LedgerNeed::UnitUsed { unit :
            types::LedgerUnit("credits".to_string()) })) })))
        );
    }

