    /// behaviour.rs every_rejection_lists_at_least_one_failed_check: unknown object type, for the owner, who may do anything, so learns that it is missing.
    #[test]
    fn object_def_example_2() {
        let d: types::Draft = fixture_fx_draft_10();
        let object: types::ObjectTypeId = types::ObjectTypeId("nothing".to_string());
        let action: types::Action = types::Action::Update;
        assert_eq!(
            object_def(&d, &object, &action),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::UnknownObject,
                    message: "no object type nothing".to_string(),
                    evidence: vec![
                        types::Check {
                            rule: "policy:builtin_owner".to_string(),
                            passed: true,
                            detail: "Update on Object(ObjectTypeId(\"nothing\"))".to_string()
                        },
                        types::Check {
                            rule: "intent:unknown_object".to_string(),
                            passed: false,
                            detail: "no object type nothing".to_string()
                        }
                    ],
                    missing: None
                }
            )))
        );
    }

