    fn effective_owners_example_2() {
        let members: std::collections::BTreeMap<
            types::PrincipalId,
            std::collections::BTreeSet<types::RoleId>,
        > = std::collections::BTreeMap::from([(
            types::PrincipalId("alpha:owner".to_string()),
            std::collections::BTreeSet::from([types::RoleId("owner".to_string())]),
        )]);
        let schema: types::TenantSchema = types::TenantSchema {
            version: types::SchemaVersion(1),
            objects: std::collections::BTreeMap::new(),
            roles: std::collections::BTreeMap::new(),
            role_permissions: None,
            teams: Some(std::collections::BTreeMap::from([(
                types::TeamId("desk".to_string()),
                types::TeamDef {
                    id: types::TeamId("desk".to_string()),
                    label: "Desk".to_string(),
                    members: std::collections::BTreeSet::from([types::PrincipalId(
                        "alpha:guest".to_string(),
                    )]),
                    roles: std::collections::BTreeSet::from([types::RoleId("owner".to_string())]),
                },
            )])),
            invitations: None,
            policies: std::collections::BTreeMap::new(),
            workflows: std::collections::BTreeMap::new(),
            queries: std::collections::BTreeMap::new(),
            views: std::collections::BTreeMap::new(),
            triggers: None,
            automations: None,
            operations: None,
            settings: None,
            capabilities: None,
            ledger: None,
            mail_templates: None,
            notice_templates: None,
            tokens: None,
            products: None,
            ui: None,
        };
        let want_: Vec<types::PrincipalId> = vec![
            types::PrincipalId("alpha:guest".to_string()),
            types::PrincipalId("alpha:owner".to_string()),
        ];
        assert_eq!(effective_owners(&members, &schema), want_);
    }

