    /// A person whose id starts with the prefix is the one.
    #[test]
    fn reserved_principal_example_1() {
        let intent: types::Intent = types::Intent::AssignRole {
            principal: types::PrincipalId("alpha:writer1".to_string()),
            role: types::RoleId("writer".to_string()),
        };
        let ctx: types::Context = types::Context {
            tenant: types::TenantId("alpha".to_string()),
            principal: types::Principal::User(types::PrincipalId("team:boss".to_string())),
            session: None,
            now: crate::prelude::Timestamp(5000),
            correlation: "test-5000".to_string(),
            verified_address: None,
            idempotency_key: None,
            language: None,
            hop: None,
        };
        let want_: Option<String> =
            Some("the principal id team:boss starts with the reserved prefix team:".to_string());
        assert_eq!(reserved_principal(&intent, &ctx), want_);
    }

