    /// Example 2 of `operation-def-problems`.
    #[test]
    fn operation_def_problems_example_2() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_10();
        let roles: Vec<types::RoleId> = vec![
            types::RoleId("editor".to_string()),
            types::RoleId("owner".to_string()),
            types::RoleId("public".to_string()),
        ];
        let op: types::TenantOperationDef = types::TenantOperationDef {
            id: types::TenantOperationId("redeem".to_string()),
            label: "Redeem".to_string(),
            inputs: vec![
                types::TenantOperationInput {
                    name: "note".to_string(),
                    ty: types::FieldType::Ref {
                        target: types::ObjectTypeId("note".to_string()),
                        on_delete: types::OnDelete::Restrict,
                    },
                    required: true,
                    label: None,
                },
                types::TenantOperationInput {
                    name: "Bad".to_string(),
                    ty: types::FieldType::Int,
                    required: false,
                    label: None,
                },
                types::TenantOperationInput {
                    name: "note".to_string(),
                    ty: types::FieldType::Int,
                    required: false,
                    label: None,
                },
            ],
            invokers: types::TenantOperationInvokers {
                signed_in: false,
                roles: std::collections::BTreeSet::from([types::RoleId("ghost".to_string())]),
            },
            subject: Some(types::TenantOperationSubject {
                object: types::ObjectTypeId("note".to_string()),
                input: "title".to_string(),
            }),
            conditions: vec![
                types::TenantOperationCondition {
                    id: "c".to_string(),
                    expr: types::Expr::Lit(types::Value::Str("x".to_string())),
                    error: "".to_string(),
                    message: "m".to_string(),
                },
                types::TenantOperationCondition {
                    id: "c".to_string(),
                    expr: types::Expr::Lit(types::Value::Str("y".to_string())),
                    error: "e".to_string(),
                    message: "m".to_string(),
                },
            ],
            steps: vec![
                types::TenantOperationStep::CreateRecord {
                    id: "copy".to_string(),
                    object: types::ObjectTypeId("note".to_string()),
                    fields: std::collections::BTreeMap::from([
                        (
                            types::FieldId("status".to_string()),
                            types::Expr::Lit(types::Value::Str("draft".to_string())),
                        ),
                        (
                            types::FieldId("title".to_string()),
                            types::Expr::Var(types::Scope::Record, "title".to_string()),
                        ),
                    ]),
                },
                types::TenantOperationStep::UpdateRecord {
                    id: "touch".to_string(),
                    object: types::ObjectTypeId("note".to_string()),
                    record: types::Expr::Param("copy".to_string()),
                    fields: std::collections::BTreeMap::from([(
                        types::FieldId("rank".to_string()),
                        types::Expr::Lit(types::Value::Int(1)),
                    )]),
                },
            ],
        };
        let want_: Vec<String> = vec![
            "operation redeem: unknown role ghost".to_string(),
            "operation redeem: input \"Bad\" is not a name".to_string(),
            "operation redeem: input note is declared twice".to_string(),
            "operation redeem: subject input title is not a reference to note".to_string(),
            "operation redeem: condition c names no error code".to_string(),
            "operation redeem: condition c is Str, not a truth value".to_string(),
            "operation redeem: condition c is Str, not a truth value".to_string(),
            "operation redeem: condition c is declared twice".to_string(),
        ];
        assert_eq!(operation_def_problems(&schema, &roles, &op), want_);
    }

