    /// Removing an automation needs automations-define.
    #[test]
    fn require_definition_authority_example_5() {
        let d: types::Draft = fixture_fx_draft_22();
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::RemoveAutomation(
            types::WorkflowId("award".to_string()),
        )];
        assert_eq!(
            require_definition_authority(&d, &changes),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::Unauthorized,
                    message: "the change needs the capability automations-define".to_string(),
                    evidence: vec![types::Check {
                        rule: "permission:capability:automations-define".to_string(),
                        passed: false,
                        detail: "does not hold automations-define".to_string()
                    }],
                    missing: None
                }
            )))
        );
    }

    /// An editor may not define an operation whose steps update notes.
    #[test]
    fn require_definition_authority_example_6() {
        let d: types::Draft = fixture_fx_draft_21();
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::DefineOperation(
            types::TenantOperationDef {
                id: types::TenantOperationId("redeem".to_string()),
                label: "Redeem".to_string(),
                inputs: vec![types::TenantOperationInput {
                    name: "note".to_string(),
                    ty: types::FieldType::Ref {
                        target: types::ObjectTypeId("note".to_string()),
                        on_delete: types::OnDelete::Restrict,
                    },
                    required: true,
                    label: None,
                }],
                invokers: types::TenantOperationInvokers {
                    signed_in: true,
                    roles: std::collections::BTreeSet::new(),
                },
                subject: Some(types::TenantOperationSubject {
                    object: types::ObjectTypeId("note".to_string()),
                    input: "note".to_string(),
                }),
                conditions: vec![types::TenantOperationCondition {
                    id: "drafted".to_string(),
                    expr: types::Expr::Cmp(
                        types::CmpOp::Eq,
                        Box::new(types::Expr::Var(types::Scope::Record, "status".to_string())),
                        Box::new(types::Expr::Lit(types::Value::Str("draft".to_string()))),
                    ),
                    error: "not-draft".to_string(),
                    message: "Only a draft.".to_string(),
                }],
                steps: vec![
                    types::TenantOperationStep::CreateRecord {
                        id: "copy".to_string(),
                        object: types::ObjectTypeId("note".to_string()),
                        fields: std::collections::BTreeMap::from([
                            (
                                types::FieldId("status".to_string()),
                                types::Expr::Lit(types::Value::Str("draft".to_string())),
                            ),
                            (
                                types::FieldId("title".to_string()),
                                types::Expr::Var(types::Scope::Record, "title".to_string()),
                            ),
                        ]),
                    },
                    types::TenantOperationStep::UpdateRecord {
                        id: "touch".to_string(),
                        object: types::ObjectTypeId("note".to_string()),
                        record: types::Expr::Param("copy".to_string()),
                        fields: std::collections::BTreeMap::from([(
                            types::FieldId("rank".to_string()),
                            types::Expr::Lit(types::Value::Int(1)),
                        )]),
                    },
                ],
            },
        )];
        assert_eq!(
            require_definition_authority(& d, & changes),
            Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
            types::ErrorKind::Unauthorized, message :
            "may not define operation redeem: lacks Update on Object(ObjectTypeId(\"note\"))"
            .to_string(), evidence : vec![types::Check { rule :
            "operation:redeem:definer_powers".to_string(), passed : false, detail :
            "Update on Object(ObjectTypeId(\"note\"))".to_string() }], missing : None
            })))
        );
    }

