    /// A retention of an unknown object type is a problem.
    #[test]
    fn apply_meta_change_example_3() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange = types::SchemaChange::SetRetention {
            object: types::ObjectTypeId("tag".to_string()),
            retention: types::RetentionRule {
                days: 365,
                from: types::RetentionStart::Created,
            },
        };
        assert_eq!(
            apply_meta_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "no object type tag".to_string()
            ))
        );
    }

