    /// A language field of an unknown object type is a problem.
    #[test]
    fn apply_meta_change_example_13() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange = types::SchemaChange::SetLanguageField {
            object: types::ObjectTypeId("tag".to_string()),
            field: types::FieldId("title".to_string()),
        };
        assert_eq!(
            apply_meta_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "no object type tag".to_string()
            ))
        );
    }

