    /// A translation group of an unknown object type is a problem.
    #[test]
    fn apply_meta_change_example_18() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange = types::SchemaChange::SetTranslationGroup {
            object: types::ObjectTypeId("tag".to_string()),
            field: types::FieldId("status".to_string()),
        };
        assert_eq!(
            apply_meta_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "no object type tag".to_string()
            ))
        );
    }

