    /// A built-in role is not removed.
    #[test]
    fn apply_meta_change_example_26() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange =
            types::SchemaChange::RemoveRole(types::RoleId("owner".to_string()));
        assert_eq!(
            apply_meta_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "owner is built in".to_string()
            ))
        );
    }

    /// A role that does not exist is not removed.
