    /// A mail template that does not exist is not removed.
    #[test]
    fn apply_meta_change_example_30() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange =
            types::SchemaChange::RemoveMailTemplate(types::TemplateId("welcome".to_string()));
        assert_eq!(
            apply_meta_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "no mail template welcome".to_string()
            ))
        );
    }

