    /// A token that does not exist is not removed.
    #[test]
    fn apply_meta_change_example_36() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange =
            types::SchemaChange::RemoveToken("first_name".to_string());
        assert_eq!(
            apply_meta_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "no token first_name".to_string()
            ))
        );
    }

