    /// An interface element that does not exist is not removed.
    #[test]
    fn apply_meta_change_example_44() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange =
            types::SchemaChange::RemoveUiElement("name-taken".to_string());
        assert_eq!(
            apply_meta_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "no interface element name-taken".to_string()
            ))
        );
    }

    /// A change of another kind is not one of these.
    #[test]
    fn apply_meta_change_example_45() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_6();
        let change: types::SchemaChange = types::SchemaChange::DefineRole(types::RoleDef {
            id: types::RoleId("guest".to_string()),
            label: "Guest".to_string(),
        });
        assert_eq!(
            apply_meta_change(&schema, &change),
            Err(types::SchemaProblem::Problem(
                "not a change of a declaration, a template, a token or a product".to_string()
            ))
        );
    }

