    fn record_json_bytes_example_1() {
        let r: types::Record = types::Record {
            id: types::RecordId(1),
            object: types::ObjectTypeId("note".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (types::FieldId("nothing".to_string()), types::Value::Null),
                (types::FieldId("rank".to_string()), types::Value::Int(-3)),
                (
                    types::FieldId("tags".to_string()),
                    types::Value::List(vec![
                        types::Value::Str("a".to_string()),
                        types::Value::Str("b".to_string()),
                    ]),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("First".to_string()),
                ),
            ]),
        };
        let want_: u64 = 213;
        assert_eq!(record_json_bytes(&r), Ok(want_));
    }

