    /// An unknown role, the owner role, a blank capability name, an unknown object type and no action.
    #[test]
    fn role_permission_problems_example_1() {
        let schema: types::TenantSchema = {
            let mut fixture = fixture_fx_tenant_schema_5();
            fixture.role_permissions = Some(std::collections::BTreeMap::from([
                (
                    types::RoleId("ghost".to_string()),
                    vec![types::Permission::Object {
                        object: types::ObjectTypeId("note".to_string()),
                        actions: std::collections::BTreeSet::from([types::ObjectAction::Read]),
                    }],
                ),
                (
                    types::RoleId("owner".to_string()),
                    vec![types::Permission::Capability("export".to_string())],
                ),
                (
                    types::RoleId("writer".to_string()),
                    vec![
                        types::Permission::Capability("  ".to_string()),
                        types::Permission::Object {
                            object: types::ObjectTypeId("nowhere".to_string()),
                            actions: std::collections::BTreeSet::new(),
                        },
                        types::Permission::Object {
                            object: types::ObjectTypeId("note".to_string()),
                            actions: std::collections::BTreeSet::from([
                                types::ObjectAction::Read,
                                types::ObjectAction::Update,
                            ]),
                        },
                    ],
                ),
            ]));
            fixture
        };
        let roles: Vec<types::RoleId> = vec![
            types::RoleId("editor".to_string()),
            types::RoleId("owner".to_string()),
            types::RoleId("public".to_string()),
            types::RoleId("writer".to_string()),
        ];
        let want_: Vec<String> = vec![
            "role ghost: permissions of an unknown role".to_string(),
            "role owner: the owner role holds every permission".to_string(),
            "role writer: a capability needs a name".to_string(),
            "role writer: permission on unknown object type nowhere".to_string(),
            "role writer: permission on nowhere names no action".to_string(),
        ];
        assert_eq!(role_permission_problems(&schema, &roles), want_);
    }

    /// No permissions, no problem.
    #[test]
    fn role_permission_problems_example_2() {
        let schema: types::TenantSchema = fixture_fx_tenant_schema_5();
        let roles: Vec<types::RoleId> = vec![
            types::RoleId("editor".to_string()),
            types::RoleId("owner".to_string()),
            types::RoleId("public".to_string()),
            types::RoleId("writer".to_string()),
        ];
        let want_: Vec<String> = Vec::new();
        assert_eq!(role_permission_problems(&schema, &roles), want_);
    }

    /// A capability of the product form must be declared; a platform capability is not checked, and a declared one may be granted by a role of the tenant (D-6590).
    #[test]
    fn role_permission_problems_example_3() {
        let schema: types::TenantSchema = {
            let mut fixture = fixture_fx_tenant_schema_31();
            fixture
                .capabilities
                .as_mut()
                .expect("the fixture value is present")
                .get_mut(&types::CapabilityName("member_tiers__promote".to_string()))
                .expect("the fixture has the key")
                .description = "d".to_string();
            fixture.role_permissions = Some(std::collections::BTreeMap::from([(
                types::RoleId("editor".to_string()),
                vec![
                    types::Permission::Capability("member_tiers__promote".to_string()),
                    types::Permission::Capability("other__thing".to_string()),
                    types::Permission::Capability("content-edit".to_string()),
                ],
            )]));
            fixture
        };
        let roles: Vec<types::RoleId> = vec![
            types::RoleId("editor".to_string()),
            types::RoleId("owner".to_string()),
            types::RoleId("public".to_string()),
            types::RoleId("writer".to_string()),
        ];
        let want_: Vec<String> = vec![
            "role editor: capability other__thing is neither a platform capability nor declared in the tenant"
            .to_string()
        ];
        assert_eq!(role_permission_problems(&schema, &roles), want_);
    }

    /// A role of another product may not grant the capability of a product.
    #[test]
    fn role_permission_problems_example_4() {
        let schema: types::TenantSchema = {
            let mut fixture = fixture_fx_tenant_schema_31();
            fixture
                .capabilities
                .as_mut()
                .expect("the fixture value is present")
                .get_mut(&types::CapabilityName("member_tiers__promote".to_string()))
                .expect("the fixture has the key")
                .description = "d".to_string();
            fixture.role_permissions = Some(std::collections::BTreeMap::from([(
                types::RoleId("crm__agent".to_string()),
                vec![types::Permission::Capability(
                    "member_tiers__promote".to_string(),
                )],
            )]));
            fixture.roles.insert(
                types::RoleId("crm__agent".to_string()),
                types::RoleDef {
                    id: types::RoleId("crm__agent".to_string()),
                    label: "Agent".to_string(),
                },
            );
            fixture
        };
        let roles: Vec<types::RoleId> = vec![
            types::RoleId("crm__agent".to_string()),
            types::RoleId("editor".to_string()),
            types::RoleId("owner".to_string()),
            types::RoleId("public".to_string()),
            types::RoleId("writer".to_string()),
        ];
        let want_: Vec<String> = vec![
            "role crm__agent: capability member_tiers__promote belongs to product member_tiers and role crm__agent to product crm"
            .to_string()
        ];
        assert_eq!(role_permission_problems(&schema, &roles), want_);
    }

