    fn rule_missing_example_1() {
        let e: types::Expr = types::Expr::Cmp(
            types::CmpOp::Eq,
            Box::new(types::Expr::Through(
                types::Scope::New,
                "author".to_string(),
                "principal".to_string(),
            )),
            Box::new(types::Expr::Principal),
        );
        let reach: types::RuleReach = fixture_fx_rule_reach_1();
        let want_: Option<types::Need> = Some(types::Need::Record {
            object: types::ObjectTypeId("author".to_string()),
            id: types::RecordId(2),
        });
        assert_eq!(rule_missing(&e, &reach), want_);
    }

