    /// publication_template.rs an_author_cannot_publish_under_another_authors_byline: with the lookup, ann files a post under her own byline; authors_write_posts holds on the author record.
    #[test]
    fn authorize_needing_example_1() {
        let tenant: types::TenantState = fixture_fx_tenant_state_25();
        let schema: types::TenantSchema = fixture_fx_tenant_schema_29();
        let principal: types::Principal =
            types::Principal::User(types::PrincipalId("user:ann".to_string()));
        let now: crate::prelude::Timestamp = crate::prelude::Timestamp(1800000000000);
        let action: types::Action = types::Action::Create;
        let resource: types::Resource =
            types::Resource::Object(types::ObjectTypeId("post".to_string()));
        let subject: types::Subject = types::Subject {
            old: None,
            new: Some(types::Record {
                id: types::RecordId(7),
                object: types::ObjectTypeId("post".to_string()),
                version: 1,
                created_by: Some(types::PrincipalId("user:ann".to_string())),
                created_at: crate::prelude::Timestamp(1800000000000),
                updated_at: crate::prelude::Timestamp(1800000000000),
                fields: std::collections::BTreeMap::from([
                    (
                        types::FieldId("author".to_string()),
                        types::Value::Ref(types::RecordId(2)),
                    ),
                    (
                        types::FieldId("title".to_string()),
                        types::Value::Str("Hello".to_string()),
                    ),
                ]),
            }),
        };
        let coverage: Option<types::Coverage> = Some(types::Coverage::Complete);
        let want_: types::PolicyDecision = types::PolicyDecision {
            allowed: true,
            checks: vec![types::PolicyCheck {
                rule: "policy:authors_write_posts".to_string(),
                passed: true,
                what: "Create on Object(ObjectTypeId(\"post\"))".to_string(),
                outcome: types::PolicyOutcome::Held,
                condition: Some(types::Expr::Cmp(
                    types::CmpOp::Eq,
                    Box::new(types::Expr::Through(
                        types::Scope::New,
                        "author".to_string(),
                        "principal".to_string(),
                    )),
                    Box::new(types::Expr::Principal),
                )),
            }],
            needed: None,
        };
        assert_eq!(
            authorize_needing(
                &tenant, &schema, &principal, now, &action, &resource, &subject, &coverage
            ),
            Ok(want_)
        );
    }

