    /// Example 1 of `trigger-decline`.
    #[test]
    fn trigger_decline_example_1() {
        let trigger: types::TriggerDef = fixture_fx_trigger_def_1();
        let event: types::DomainEvent = fixture_fx_domain_event_2();
        let hop: u32 = 3;
        let reason: types::AutomationExceptionReason = types::AutomationExceptionReason::HopLimit;
        let text: String = "hop 9 is past the hop limit of 8".to_string();
        let want_: types::Effect = types::Effect::DeclineAutomation(types::AutomationDecline {
            trigger: types::TriggerId("on_publish".to_string()),
            automation: types::WorkflowId("award".to_string()),
            event_seq: 7,
            hop: 3,
            reason: types::AutomationExceptionReason::HopLimit,
            detail: "hop 9 is past the hop limit of 8".to_string(),
        });
        assert_eq!(
            trigger_decline(&trigger, &event, hop, &reason, &text),
            want_
        );
    }

    /// Example 1 of `trigger-start`.
    #[test]
    fn trigger_start_example_1() {
        let after: types::TenantState = fixture_fx_tenant_state_9();
        let a: types::AutomationDef = types::AutomationDef {
            id: types::WorkflowId("award".to_string()),
            label: "award".to_string(),
            run_as: types::RunAs {
                roles: std::collections::BTreeSet::from([types::RoleId("editor".to_string())]),
            },
            run_key: None,
            start: types::StepName("done".to_string()),
            steps: std::collections::BTreeMap::from([(
                types::StepName("done".to_string()),
                types::AutomationStepDef {
                    action: types::AutomationStep::End,
                    next: None,
                    retry: None,
                    timeout: None,
                    compensate: None,
                },
            )]),
            defined_by: Some(types::PrincipalId("alpha:owner".to_string())),
            defined_at: Some(crate::prelude::Timestamp(4000)),
            suspended_for: None,
            state: None,
        };
        let trigger: types::TriggerDef = fixture_fx_trigger_def_1();
        let event: types::DomainEvent = fixture_fx_domain_event_2();
        let hop: u32 = 1;
        let params: std::collections::BTreeMap<String, types::Value> =
            std::collections::BTreeMap::from([("seq".to_string(), types::Value::Int(7))]);
        let run_key: Option<String> = Some("{\"Int\":7}".to_string());
        let want_: types::Effect = types::Effect::StartAutomation(types::AutomationStart {
            trigger: types::TriggerId("on_publish".to_string()),
            automation: types::WorkflowId("award".to_string()),
            event_seq: 7,
            hop: 1,
            caused_by: types::PrincipalId("automation:award".to_string()),
            on_behalf_of: Some(types::PrincipalId("alpha:owner".to_string())),
            definition_version: types::SchemaVersion(2),
            run_key: Some("{\"Int\":7}".to_string()),
            params: std::collections::BTreeMap::from([("seq".to_string(), types::Value::Int(7))]),
        });
        assert_eq!(
            trigger_start(&after, &a, &trigger, &event, hop, &params, &run_key),
            Ok(want_)
        );
    }

    /// A condition that holds and no run key start the run.
