    /// A string past the longest a field holds.
    #[test]
    fn setting_type_problem_example_5() {
        let ty: String = "string".to_string();
        let value: types::Value = types::Value::Str(
            ""
                .to_string(),
        );
        let want_: Option<types::SettingProblem> = Some(types::SettingProblem {
            kind: types::ErrorKind::LimitExceeded,
            message: "a string of 65537 bytes is longer than the maximum of 65536".to_string(),
        });
        assert_eq!(setting_type_problem(&ty, &value), Ok(want_));
    }

    /// A value of another type.
    #[test]
    fn setting_type_problem_example_6() {
        let ty: String = "bool".to_string();
        let value: types::Value = types::Value::Str("yes".to_string());
        let want_: Option<types::SettingProblem> = Some(types::SettingProblem {
            kind: types::ErrorKind::TypeMismatch,
            message: "a string is not a value of type bool".to_string(),
        });
        assert_eq!(setting_type_problem(&ty, &value), Ok(want_));
    }

