    /// Of two teams of the person, the first in id order.
    #[test]
    fn setting_found_of_example_4() {
        let tenant: types::TenantState = {
            let mut fixture = fixture_fx_tenant_state_32();
            fixture.setting_values = Some(std::sync::Arc::new(types::SettingValues {
                overrides: std::collections::BTreeMap::from([
                    (
                        "theme/team/desk".to_string(),
                        types::SettingOverride {
                            setting: types::SettingId("theme".to_string()),
                            level: types::SettingLevel::Team,
                            subject: "desk".to_string(),
                            value: types::Value::Str("red".to_string()),
                            revision: 1,
                            set_by: types::PrincipalId("alpha:owner".to_string()),
                            set_at: crate::prelude::Timestamp(4000),
                        },
                    ),
                    (
                        "theme/team/lab".to_string(),
                        types::SettingOverride {
                            setting: types::SettingId("theme".to_string()),
                            level: types::SettingLevel::Team,
                            subject: "lab".to_string(),
                            value: types::Value::Str("blue".to_string()),
                            revision: 1,
                            set_by: types::PrincipalId("alpha:owner".to_string()),
                            set_at: crate::prelude::Timestamp(4000),
                        },
                    ),
                ]),
                revisions: std::collections::BTreeMap::from([(
                    types::SettingId("theme".to_string()),
                    2,
                )]),
            }));
            fixture
        };
        let def: types::SettingDef = types::SettingDef {
            id: types::SettingId("theme".to_string()),
            label: "theme".to_string(),
            r#type: types::SettingType("string".to_string()),
            default: types::Value::Str("light".to_string()),
            levels: std::collections::BTreeSet::from([
                types::SettingLevel::Tenant,
                types::SettingLevel::Team,
                types::SettingLevel::Person,
            ]),
            locked_by: None,
        };
        let principal: types::Principal =
            types::Principal::User(types::PrincipalId("alpha:writer1".to_string()));
        let want_: types::SettingFound = types::SettingFound {
            source: types::SettingSource::Team,
            team: Some(types::TeamId("desk".to_string())),
            value: types::Value::Str("red".to_string()),
        };
        assert_eq!(setting_found_of(&tenant, &def, &principal), want_);
    }

