    /// Only a signed-in person writes.
    #[test]
    fn write_setting_example_5() {
        let d: types::Draft = {
            let mut fixture = fixture_fx_draft_26();
            fixture.ctx.correlation = "test-5000".to_string();
            fixture.ctx.principal = types::Principal::Anonymous;
            fixture
        };
        let setting: types::SettingId = types::SettingId("theme".to_string());
        let level: types::SettingLevel = types::SettingLevel::Tenant;
        let team: Option<types::TeamId> = None;
        let value: Option<types::Value> = Some(types::Value::Str("x".to_string()));
        let expected_revision: u64 = 3;
        assert_eq!(
            write_setting(&d, &setting, &level, &team, &value, expected_revision),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::Unauthorized,
                    message: "only a signed-in person writes a setting".to_string(),
                    evidence: vec![types::Check {
                        rule: "setting:caller_is_a_person".to_string(),
                        passed: false,
                        detail: "only a signed-in person writes a setting".to_string()
                    }],
                    missing: None
                }
            )))
        );
    }

    /// The platform level is the control plane's.
    #[test]
    fn write_setting_example_6() {
        let d: types::Draft = fixture_fx_draft_26();
        let setting: types::SettingId = types::SettingId("theme".to_string());
        let level: types::SettingLevel = types::SettingLevel::Platform;
        let team: Option<types::TeamId> = None;
        let value: Option<types::Value> = Some(types::Value::Str("x".to_string()));
        let expected_revision: u64 = 0;
        assert_eq!(
            write_setting(&d, &setting, &level, &team, &value, expected_revision),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::InvalidIntent,
                    message: "the platform level of a setting is written by the control plane"
                        .to_string(),
                    evidence: vec![
                        types::Check {
                            rule: "setting:caller_is_a_person".to_string(),
                            passed: true,
                            detail: "alpha:owner".to_string()
                        },
                        types::Check {
                            rule: "setting:platform_level_is_the_control_planes".to_string(),
                            passed: false,
                            detail:
                                "the platform level of a setting is written by the control plane"
                                    .to_string()
                        }
                    ],
                    missing: None
                }
            )))
        );
    }

    /// A writer may not write the tenant level.
    #[test]
    fn write_setting_example_7() {
        let d: types::Draft = fixture_fx_draft_27();
        let setting: types::SettingId = types::SettingId("theme".to_string());
        let level: types::SettingLevel = types::SettingLevel::Tenant;
        let team: Option<types::TeamId> = None;
        let value: Option<types::Value> = Some(types::Value::Str("x".to_string()));
        let expected_revision: u64 = 3;
        assert_eq!(
            write_setting(&d, &setting, &level, &team, &value, expected_revision),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::Unauthorized,
                    message:
                        "a write at the tenant level needs the capability setting-write-tenant"
                            .to_string(),
                    evidence: vec![types::Check { rule :
            "setting:caller_is_a_person".to_string(), passed : true, detail :
            "alpha:writer1".to_string() }, types::Check { rule :
            "permission:capability:setting-write-tenant".to_string(), passed : false,
            detail :
            "a write at the tenant level needs the capability setting-write-tenant"
            .to_string() }],
                    missing: None
                }
            )))
        );
    }

