    /// A setting defined for the first time: its revision is the first and an event names it.
    #[test]
    fn setting_effects_step_example_1() {
        let tenant: types::TenantState = fixture_fx_tenant_state_36();
        let acc: types::SettingEffectsAcc = types::SettingEffectsAcc {
            ops: Vec::new(),
            events: Vec::new(),
            revisions: std::collections::BTreeMap::new(),
            types: std::collections::BTreeMap::new(),
            emptied: Vec::new(),
            problem: None,
        };
        let id: types::SettingId = types::SettingId("mode".to_string());
        let after: String = "string".to_string();
        let removal: bool = false;
        let want_: types::SettingEffectsAcc = types::SettingEffectsAcc {
            ops: Vec::new(),
            events: vec![types::EventBody::SettingChanged {
                setting: types::SettingId("mode".to_string()),
                level: types::SettingLevel::Tenant,
                subject: "alpha".to_string(),
            }],
            revisions: std::collections::BTreeMap::from([(
                types::SettingId("mode".to_string()),
                1,
            )]),
            types: std::collections::BTreeMap::from([(
                types::SettingId("mode".to_string()),
                "string".to_string(),
            )]),
            emptied: Vec::new(),
            problem: None,
        };
        assert_eq!(
            setting_effects_step(&tenant, &acc, &id, &after, removal),
            Ok(want_)
        );
    }

