    /// A unit and a pool declared under another name.
    #[test]
    fn ledger_problems_example_5() {
        let schema: types::TenantSchema = {
            let mut fixture = fixture_fx_tenant_schema_6();
            fixture.ledger = Some(types::LedgerDeclarations {
                units: std::collections::BTreeMap::from([(
                    types::LedgerUnit("credits".to_string()),
                    types::LedgerUnitDecl {
                        unit: types::LedgerUnit("points".to_string()),
                        description: "points".to_string(),
                        expiry: None,
                    },
                )]),
                pools: std::collections::BTreeMap::from([(
                    types::LedgerPoolName("promo".to_string()),
                    types::LedgerPoolDecl {
                        pool: types::LedgerPoolName("other".to_string()),
                        description: "other".to_string(),
                    },
                )]),
                limits: Vec::new(),
            });
            fixture
        };
        let want_: Vec<String> = vec![
            "ledger unit credits: declared under another name".to_string(),
            "ledger pool promo: declared under another name".to_string(),
        ];
        assert_eq!(ledger_problems(&schema), Ok(want_));
    }

    /// The problems of each limit, in the order held.
    #[test]
    fn ledger_problems_example_6() {
        let schema: types::TenantSchema = {
            let mut fixture = fixture_fx_tenant_schema_32();
            fixture
                .ledger
                .as_mut()
                .expect("the fixture value is present")
                .limits = vec![
                types::LedgerLimit {
                    unit: types::LedgerUnit("credits".to_string()),
                    owner: None,
                    floor: None,
                    cap: Some(types::LedgerAmount(5)),
                    period_cap: None,
                    period: None,
                    scope: None,
                },
                types::LedgerLimit {
                    unit: types::LedgerUnit("points".to_string()),
                    owner: None,
                    floor: None,
                    cap: Some(types::LedgerAmount(1)),
                    period_cap: None,
                    period: None,
                    scope: None,
                },
                types::LedgerLimit {
                    unit: types::LedgerUnit("credits".to_string()),
                    owner: None,
                    floor: None,
                    cap: None,
                    period_cap: None,
                    period: None,
                    scope: None,
                },
            ];
            fixture
        };
        let want_: Vec<String> = vec![
            "ledger limit of points: unknown ledger unit points".to_string(),
            "ledger limit of credits: sets no limit".to_string(),
        ];
        assert_eq!(ledger_problems(&schema), Ok(want_));
    }

    /// Example 1 of `ledger-change-needs`.
    #[test]
    fn ledger_change_needs_example_1() {
        let changes: Vec<types::SchemaChange> = Vec::new();
        let want_: Vec<types::Need> = Vec::new();
        assert_eq!(ledger_change_needs(&changes), want_);
    }

    /// Example 2 of `ledger-change-needs`.
    #[test]
    fn ledger_change_needs_example_2() {
        let changes: Vec<types::SchemaChange> = vec![
            types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Unit {
                unit: types::LedgerUnit("credits".to_string()),
            }),
            types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Pool {
                pool: types::LedgerPoolName("promo".to_string()),
            }),
            types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Limit {
                unit: types::LedgerUnit("credits".to_string()),
                owner: None,
                scope: None,
            }),
            types::SchemaChange::DeclareLedgerUnit(types::LedgerUnitDecl {
                unit: types::LedgerUnit("x".to_string()),
                description: "x".to_string(),
                expiry: None,
            }),
        ];
        let want_: Vec<types::Need> = vec![
            types::Need::Ledger(types::LedgerNeed::UnitUsed {
                unit: types::LedgerUnit("credits".to_string()),
            }),
            types::Need::Ledger(types::LedgerNeed::PoolUsed {
                pool: types::LedgerPoolName("promo".to_string()),
            }),
        ];
        assert_eq!(ledger_change_needs(&changes), want_);
    }

