    /// A snapshot that does not cover the need of a pool is InsufficientState too.
    #[test]
    fn ledger_removal_check_example_5() {
        let d: types::Draft = fixture_fx_draft_29();
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::RemoveLedgerDefinition(
            types::LedgerDefinitionRef::Pool {
                pool: types::LedgerPoolName("promo".to_string()),
            },
        )];
        assert_eq!(
            ledger_removal_check(& d, & changes),
            Err(types::Rejection::Rejected(types::DomainError { kind :
            types::ErrorKind::InsufficientState, message :
            "the snapshot does not cover Ledger(PoolUsed { pool: LedgerPoolName(\"promo\") })"
            .to_string(), evidence : vec![types::Check { rule : "coverage".to_string(),
            passed : false, detail :
            "Ledger(PoolUsed { pool: LedgerPoolName(\"promo\") })".to_string() }],
            missing : Some(types::Need::Ledger(types::LedgerNeed::PoolUsed { pool :
            types::LedgerPoolName("promo".to_string()) })) }))
        );
    }

    /// A snapshot that does not cover the need is InsufficientState.
    #[test]
    fn ledger_removal_check_example_6() {
        let d: types::Draft = fixture_fx_draft_29();
        let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::RemoveLedgerDefinition(
            types::LedgerDefinitionRef::Unit {
                unit: types::LedgerUnit("credits".to_string()),
            },
        )];
        assert_eq!(
            ledger_removal_check(&d, &changes),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::InsufficientState,
                message:
                    "the snapshot does not cover Ledger(UnitUsed { unit: LedgerUnit(\"credits\") })"
                        .to_string(),
                evidence: vec![types::Check {
                    rule: "coverage".to_string(),
                    passed: false,
                    detail: "Ledger(UnitUsed { unit: LedgerUnit(\"credits\") })".to_string()
                }],
                missing: Some(types::Need::Ledger(types::LedgerNeed::UnitUsed {
                    unit: types::LedgerUnit("credits".to_string())
                }))
            }))
        );
    }

