    /// Example 3 of `ledger-removal-step`.
    #[test]
    fn ledger_removal_step_example_3() {
        let d: types::Draft = fixture_fx_draft_29();
        let wanted: types::Need = types::Need::Ledger(types::LedgerNeed::UnitUsed {
            unit: types::LedgerUnit("credits".to_string()),
        });
        let what: String = "ledger unit credits".to_string();
        let used: bool = false;
        assert_eq!(
            ledger_removal_step(&d, &wanted, &what, used),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::InsufficientState,
                message:
                    "the snapshot does not cover Ledger(UnitUsed { unit: LedgerUnit(\"credits\") })"
                        .to_string(),
                evidence: vec![types::Check {
                    rule: "coverage".to_string(),
                    passed: false,
                    detail: "Ledger(UnitUsed { unit: LedgerUnit(\"credits\") })".to_string()
                }],
                missing: Some(types::Need::Ledger(types::LedgerNeed::UnitUsed {
                    unit: types::LedgerUnit("credits".to_string())
                }))
            }))
        );
    }

    /// An account names the unit: StillReferenced, after the checks that passed.
    #[test]
    fn ledger_removal_step_example_4() {
        let d: types::Draft = {
            let mut fixture = fixture_fx_draft_28();
            fixture.evidence = vec![types::Check {
                rule: "x".to_string(),
                passed: true,
                detail: "y".to_string(),
            }];
            fixture
        };
        let wanted: types::Need = types::Need::Ledger(types::LedgerNeed::UnitUsed {
            unit: types::LedgerUnit("credits".to_string()),
        });
        let what: String = "ledger unit credits".to_string();
        let used: bool = true;
        assert_eq!(
            ledger_removal_step(&d, &wanted, &what, used),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::StillReferenced,
                message: "ledger unit credits is named by an account and is not removed"
                    .to_string(),
                evidence: vec![
                    types::Check {
                        rule: "x".to_string(),
                        passed: true,
                        detail: "y".to_string()
                    },
                    types::Check {
                        rule: "ledger:in-use".to_string(),
                        passed: false,
                        detail: "ledger unit credits is named by an account and is not removed"
                            .to_string()
                    }
                ],
                missing: None
            }))
        );
    }

