    /// A system attribute is not a field.
    #[test]
    fn mentions_field_example_1() {
        let e: types::Expr = types::Expr::Cmp(
            types::CmpOp::Eq,
            Box::new(types::Expr::Var(
                types::Scope::Record,
                "$created_by".to_string(),
            )),
            Box::new(types::Expr::Principal),
        );
        assert!(!mentions_field(&e));
    }

    /// A field read in a branch that never runs is a field read.
    #[test]
    fn mentions_field_example_2() {
        let e: types::Expr = types::Expr::If(
            Box::new(types::Expr::Lit(types::Value::Bool(true))),
            Box::new(types::Expr::Lit(types::Value::Bool(true))),
            Box::new(types::Expr::Cmp(
                types::CmpOp::Eq,
                Box::new(types::Expr::Var(types::Scope::Record, "status".to_string())),
                Box::new(types::Expr::Lit(types::Value::Str("x".to_string()))),
            )),
        );
        assert!(mentions_field(&e));
    }

    /// A read through a reference reads a field.
    #[test]
    fn mentions_field_example_3() {
        let e: types::Expr = types::Expr::Not(Box::new(types::Expr::IsNull(Box::new(
            types::Expr::Through(
                types::Scope::Record,
                "author".to_string(),
                "name".to_string(),
            ),
        ))));
        assert!(mentions_field(&e));
    }

    /// Deep in an and of an or.
    #[test]
    fn mentions_field_example_4() {
        let e: types::Expr = types::Expr::And(vec![
            types::Expr::HasRole(types::RoleId("writer".to_string())),
            types::Expr::Or(vec![
                types::Expr::Lit(types::Value::Bool(false)),
                types::Expr::Cmp(
                    types::CmpOp::Gt,
                    Box::new(types::Expr::Len(Box::new(types::Expr::Lower(Box::new(
                        types::Expr::Var(types::Scope::Record, "title".to_string()),
                    ))))),
                    Box::new(types::Expr::Lit(types::Value::Int(3))),
                ),
            ]),
        ]);
        assert!(mentions_field(&e));
    }

    /// Every other operator is walked into, operand by operand: none of these reads a field.
    #[test]
    fn mentions_field_example_5() {
        let e: types::Expr = types::Expr::And(vec![
            types::Expr::IsSlug(Box::new(types::Expr::Lit(types::Value::Str(
                "a".to_string(),
            )))),
            types::Expr::Text(Box::new(types::Expr::Lit(types::Value::Int(1)))),
            types::Expr::Duration(
                types::DurationUnit::Days,
                Box::new(types::Expr::Lit(types::Value::Int(1))),
            ),
            types::Expr::In(
                Box::new(types::Expr::Lit(types::Value::Int(1))),
                Box::new(types::Expr::Lit(types::Value::List(Vec::new()))),
            ),
            types::Expr::Contains(
                Box::new(types::Expr::Lit(types::Value::Str("ab".to_string()))),
                Box::new(types::Expr::Lit(types::Value::Str("a".to_string()))),
            ),
            types::Expr::StartsWith(
                Box::new(types::Expr::Lit(types::Value::Str("ab".to_string()))),
                Box::new(types::Expr::Lit(types::Value::Str("a".to_string()))),
            ),
            types::Expr::Arith(
                types::ArithOp::Add,
                Box::new(types::Expr::Lit(types::Value::Int(1))),
                Box::new(types::Expr::Lit(types::Value::Int(2))),
            ),
            types::Expr::MsBetween(Box::new(types::Expr::Now), Box::new(types::Expr::Now)),
            types::Expr::Concat(
                Box::new(types::Expr::Lit(types::Value::Str("a".to_string()))),
                Box::new(types::Expr::Lit(types::Value::Str("b".to_string()))),
            ),
        ]);
        assert!(!mentions_field(&e));
    }

    /// A field read as the operand of a concatenation in a duration is found.
    #[test]
    fn mentions_field_example_6() {
        let e: types::Expr = types::Expr::Duration(
            types::DurationUnit::Hours,
            Box::new(types::Expr::Concat(
                Box::new(types::Expr::Lit(types::Value::Str("a".to_string()))),
                Box::new(types::Expr::Var(types::Scope::Record, "title".to_string())),
            )),
        );
        assert!(mentions_field(&e));
    }

    /// Literals, parameters, now, the principal and role tests read no field.
    #[test]
    fn mentions_field_example_7() {
        let e: types::Expr = types::Expr::And(vec![
            types::Expr::HasRole(types::RoleId("writer".to_string())),
            types::Expr::Cmp(
                types::CmpOp::Eq,
                Box::new(types::Expr::Param("x".to_string())),
                Box::new(types::Expr::Now),
            ),
        ]);
        assert!(!mentions_field(&e));
    }

