    /// Example 1 of `ledger-refused`.
    #[test]
    fn ledger_refused_example_1() {
        let evidence: Vec<types::Check> = vec![types::Check {
            rule: "ledger:unit".to_string(),
            passed: true,
            detail: "unit credits is declared".to_string(),
        }];
        let kind: types::ErrorKind = types::ErrorKind::InvalidIntent;
        let rule: String = "ledger:invalid-amount".to_string();
        let message: String = "not 0".to_string();
        let want_: types::DomainError = types::DomainError {
            kind: types::ErrorKind::InvalidIntent,
            message: "ledger:invalid-amount: not 0".to_string(),
            evidence: vec![
                types::Check {
                    rule: "ledger:unit".to_string(),
                    passed: true,
                    detail: "unit credits is declared".to_string(),
                },
                types::Check {
                    rule: "ledger:invalid-amount".to_string(),
                    passed: false,
                    detail: "not 0".to_string(),
                },
            ],
            missing: None,
        };
        assert_eq!(ledger_refused(&evidence, &kind, &rule, &message), want_);
    }

