    /// A first posting that fails a check before its account is refused as the kernel refuses it.
    #[test]
    fn ledger_intent_decision_example_4() {
        let d: types::Draft = fixture_fx_draft_30();
        let postings: Vec<types::LedgerPostingRequest> = vec![
            types::LedgerPostingRequest {
                owner: types::LedgerOwner::Principal {
                    principal: types::PrincipalId("alpha:owner".to_string()),
                },
                unit: types::LedgerUnit("credits".to_string()),
                amount: types::LedgerAmount(0),
                idempotency_key: "k1".to_string(),
                reason: "a reward".to_string(),
                corrects: None,
                scope: None,
            },
            types::LedgerPostingRequest {
                owner: types::LedgerOwner::Principal {
                    principal: types::PrincipalId("alpha:owner".to_string()),
                },
                unit: types::LedgerUnit("credits".to_string()),
                amount: types::LedgerAmount(5),
                idempotency_key: "k2".to_string(),
                reason: "a reward".to_string(),
                corrects: None,
                scope: None,
            },
        ];
        assert_eq!(
            ledger_intent_decision(& d, & postings),
            Err(Failure::Error(types::Rejection::Rejected(types::DomainError { kind :
            types::ErrorKind::InvalidIntent, message :
            "ledger:invalid-amount: an amount is a whole number from -9007199254740991 to 9007199254740991 other than 0, not 0"
            .to_string(), evidence : vec![types::Check { rule :
            "permission:capability:ledger-post".to_string(), passed : true, detail :
            "holds ledger-post".to_string() }, types::Check { rule : "ledger:unit"
            .to_string(), passed : true, detail : "unit credits is declared".to_string()
            }, types::Check { rule : "ledger:owner".to_string(), passed : true, detail :
            "the owner exists".to_string() }, types::Check { rule :
            "ledger:invalid-amount".to_string(), passed : false, detail :
            "an amount is a whole number from -9007199254740991 to 9007199254740991 other than 0, not 0"
            .to_string() }], missing : None })))
        );
    }

    /// A first posting that passes those checks: the checks that passed, after which the kernel ledger module reads the account.
    #[test]
    fn ledger_intent_decision_example_5() {
        let d: types::Draft = fixture_fx_draft_30();
        let postings: Vec<types::LedgerPostingRequest> = vec![
            types::LedgerPostingRequest {
                owner: types::LedgerOwner::Principal {
                    principal: types::PrincipalId("alpha:owner".to_string()),
                },
                unit: types::LedgerUnit("credits".to_string()),
                amount: types::LedgerAmount(5),
                idempotency_key: "k1".to_string(),
                reason: "a reward".to_string(),
                corrects: None,
                scope: None,
            },
            types::LedgerPostingRequest {
                owner: types::LedgerOwner::Principal {
                    principal: types::PrincipalId("alpha:owner".to_string()),
                },
                unit: types::LedgerUnit("credits".to_string()),
                amount: types::LedgerAmount(0),
                idempotency_key: "k2".to_string(),
                reason: "a reward".to_string(),
                corrects: None,
                scope: None,
            },
        ];
        let want_: Vec<types::Check> = vec![
            types::Check {
                rule: "permission:capability:ledger-post".to_string(),
                passed: true,
                detail: "holds ledger-post".to_string(),
            },
            types::Check {
                rule: "ledger:unit".to_string(),
                passed: true,
                detail: "unit credits is declared".to_string(),
            },
            types::Check {
                rule: "ledger:owner".to_string(),
                passed: true,
                detail: "the owner exists".to_string(),
            },
        ];
        assert_eq!(ledger_intent_decision(&d, &postings), Ok(want_));
    }

